export function lastEnd(
  threadId: string,
  events: SessionEvent[]
): Extract<SessionEvent, { kind: 'agent.end' }> | undefined {
  for (let i = events.length - 1; i >= 0; i--) {
    const e = events[i]
    if (e.kind === 'agent.end' && e.threadId === threadId) return e
  }
  return undefined
}

