    const shape = subagentShape(id)
    const art = coverFor({ id, colors: paletteFor(id) })
    const path = new Path2D(shapePath(shape, box))
    paint.save()
    paint.translate(x, y)
    paint.clip(path)
    if (art) paint.drawImage(art, 0, 0, box, box)
    else {
